import{_ as i,l as s,o as e,c as l,v as t,p as n,x as o,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"对准传感器 SMASH / ORION","description":"","frontmatter":{"title":"对准传感器 SMASH / ORION","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/alignment-sensors.md","filePath":"litho/alignment-sensors.md","lastUpdated":1789023840000}'),m={name:"litho/alignment-sensors.md"};function _(A,a,c,E,S,u){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="对准传感器-smash-orion" tabindex="-1">对准传感器 SMASH / ORION <a class="header-anchor" href="#对准传感器-smash-orion" aria-label="Permalink to &quot;对准传感器 SMASH / ORION&quot;">​</a></h1><div class="epigraph"><p>对准传感器读的是标记衍射或成像，不是器件图形。SMASH、ORION 是公开产品名背后的通道：颜色、偏振、阶次怎么组合抗工艺。</p><footer>—— 对照 ASML SMASH / ORION 公开对准光学；[对准策略](/litho/alignment-spm)</footer></div><p><a href="/litho/focus-sensor-topography">上一课</a>跟 Z。缺口是 XY 网格：相对上一层或零层标记把掩模场放对。主干对准策略课已有 SPM；本课落到传感器硬件名与通道，不重写套刻定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标记被薄膜、CMP、不对称刻蚀损坏后，单色成像对准会偏。多波长、多阶衍射（公开叙述中 SMASH 一类）提高对工艺的稳健。把套刻坏了只写成台编码器，会漏掉标记不对称。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>传感器选波长/偏振/捕获阶次，拟合标记位置。配方按层选通道。ORION 等后续公开名强调对先进节点标记对比。与 <a href="/litho/dbo-ibo">DBO</a> 分工：对准是曝光前放场，套刻计量是曝光后验残差。</p>',7)),(e(),n(p,null,{default:o(()=>[h(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20MK%5B%22%E6%99%B6%E5%9C%86%E6%A0%87%E8%AE%B0%22%5D%20--%3E%20CH%5B%22%E5%A4%9A%E8%89%B2%20%2F%20%E5%A4%9A%E9%98%B6%E9%80%9A%E9%81%93%22%5D%0A%20%20CH%20--%3E%20XY%5B%22%E7%BD%91%E6%A0%BC%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20XY%20--%3E%20EXP%5B%22%E6%9B%9D%E5%85%89%E5%9C%BA%E6%94%BE%E7%BD%AE%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">产品名会换代。本课用公开名指「多通道对准光学」这一类，不把某年手册当唯一实现。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>衍射对准看 ±1 阶相位；不对称叠层让两阶不等，位置偏。多色可以把不同穿透深度的信息合起来压偏置。成像对准则吃对比度与焦。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课标记怎么画：传感器再好，坏标记设计也救不回来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对准传感器用多通道抗工艺，读标记不读器件。</li><li>与曝光后套刻计量分时、分目的。</li><li>出处：对准策略课；SMASH/ORION 公开描述。</li></ul>',7))])}const O=i(m,[["render",_]]);export{B as __pageData,O as default};
